#include "crypto.h"
typedef struct{uint32_t h[8];uint64_t bits;uint8_t b[64];size_t n;}sha_t;
static const uint32_t k[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
static uint32_t rr(uint32_t x,int n){return(x>>n)|(x<<(32-n));}static void init(sha_t*s){uint32_t h[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};for(int i=0;i<8;i++)s->h[i]=h[i];s->bits=0;s->n=0;}
static void block(sha_t*s,const uint8_t*p){uint32_t w[64];for(int i=0;i<16;i++)w[i]=(uint32_t)p[i*4]<<24|(uint32_t)p[i*4+1]<<16|(uint32_t)p[i*4+2]<<8|p[i*4+3];for(int i=16;i<64;i++){uint32_t a=rr(w[i-15],7)^rr(w[i-15],18)^(w[i-15]>>3),b=rr(w[i-2],17)^rr(w[i-2],19)^(w[i-2]>>10);w[i]=w[i-16]+a+w[i-7]+b;}uint32_t a=s->h[0],b=s->h[1],c=s->h[2],d=s->h[3],e=s->h[4],f=s->h[5],g=s->h[6],h=s->h[7];for(int i=0;i<64;i++){uint32_t s1=rr(e,6)^rr(e,11)^rr(e,25),ch=(e&f)^(~e&g),t1=h+s1+ch+k[i]+w[i],s0=rr(a,2)^rr(a,13)^rr(a,22),maj=(a&b)^(a&c)^(b&c),t2=s0+maj;h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;}s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h;}
static void update(sha_t*s,const uint8_t*p,size_t n){s->bits+=(uint64_t)n*8;while(n){size_t x=64-s->n;if(x>n)x=n;for(size_t i=0;i<x;i++)s->b[s->n+i]=p[i];s->n+=x;p+=x;n-=x;if(s->n==64){block(s,s->b);s->n=0;}}}static void final(sha_t*s,uint8_t out[32]){uint64_t bits=s->bits;s->b[s->n++]=0x80;if(s->n>56){while(s->n<64)s->b[s->n++]=0;block(s,s->b);s->n=0;}while(s->n<56)s->b[s->n++]=0;for(int i=7;i>=0;i--)s->b[s->n++]=(uint8_t)(bits>>(i*8));block(s,s->b);for(int i=0;i<8;i++){out[i*4]=s->h[i]>>24;out[i*4+1]=s->h[i]>>16;out[i*4+2]=s->h[i]>>8;out[i*4+3]=s->h[i];}}
static void hmac(const uint8_t*key,size_t kn,const uint8_t*msg,size_t mn,uint8_t out[32]){uint8_t k0[64],inner[32];for(int i=0;i<64;i++)k0[i]=0;if(kn>64){sha_t s;init(&s);update(&s,key,kn);final(&s,k0);kn=32;}else for(size_t i=0;i<kn;i++)k0[i]=key[i];for(int i=0;i<64;i++)k0[i]^=0x36;sha_t s;init(&s);update(&s,k0,64);update(&s,msg,mn);final(&s,inner);for(int i=0;i<64;i++)k0[i]^=0x36^0x5c;init(&s);update(&s,k0,64);update(&s,inner,32);final(&s,out);}
void pbkdf2_sha256(const uint8_t*p,size_t pn,const uint8_t*salt,size_t sn,uint32_t rounds,uint8_t out[32]){uint8_t msg[68],u[32];if(sn>64)sn=64;for(size_t i=0;i<sn;i++)msg[i]=salt[i];msg[sn]=0;msg[sn+1]=0;msg[sn+2]=0;msg[sn+3]=1;hmac(p,pn,msg,sn+4,u);for(int i=0;i<32;i++)out[i]=u[i];for(uint32_t r=1;r<rounds;r++){hmac(p,pn,u,32,u);for(int i=0;i<32;i++)out[i]^=u[i];}}
